import java.util.*;
import java.io.*;

public class Main {
    public static int[][] merge(int[][] intervals) {
        if (intervals.length == 0) return new int[0][2];
        Arrays.sort(intervals, (a, b) -> Integer.compare(a[0], b[0]));
        List<int[]> res = new ArrayList<>();
        res.add(intervals[0]);
        for (int i = 1; i < intervals.length; i++) {
            int[] last = res.get(res.size() - 1);
            if (intervals[i][0] <= last[1]) {
                last[1] = Math.max(last[1], intervals[i][1]);
            } else {
                res.add(intervals[i]);
            }
        }
        return res.toArray(new int[0][]);
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder sb = new StringBuilder();
        String line; while((line = br.readLine()) != null) sb.append(line);
        String s = sb.toString().trim();
        if (s.isEmpty()) return;
        List<int[]> list = new ArrayList<>();
        int i = 0;
        while(i < s.length()) {
            if(s.charAt(i) == '[') {
                int j = i + 1;
                while(j < s.length() && s.charAt(j) != '[') {
                    if(s.charAt(j) == ']') break;
                    j++;
                }
                if(j < s.length() && s.charAt(j) == '[') {
                    int k = j + 1;
                    while(k < s.length() && s.charAt(k) != ']') k++;
                    String[] parts = s.substring(j+1, k).replace(",", " ").trim().split("\\s+");
                    if(parts.length == 2) list.add(new int[]{Integer.parseInt(parts[0]), Integer.parseInt(parts[1])});
                    i = k + 1;
                } else i++;
            } else i++;
        }
        int[][] res = merge(list.toArray(new int[0][]));
        System.out.print("[");
        for(int k=0; k<res.length; k++) {
            System.out.print("[" + res[k][0] + "," + res[k][1] + "]" + (k == res.length-1 ? "" : ","));
        }
        System.out.println("]");
    }
}

